// Spring finds this automatically via component scan
@Service  // @Component + service layer semantics
public class UserService {
    @Autowired
    private UserRepository repo;
    public User findById(Long id) { return repo.findById(id).orElseThrow(); }
}
// No need to explicitly register — component scan handles it

// Good: main class in root package
package com.example.myapp;
@SpringBootApplication
public class MyApp { ... }
// Scans: com.example.myapp.*, com.example.myapp.service.*, etc.

// Problem: bean in unscanned package
package com.example.util; // NOT a sub-package of com.example.myapp
@Component
public class HelperUtil { ... } // NOT found!

@SpringBootApplication
@ComponentScan(basePackages = {
    "com.example.myapp",   // must include your own package too
    "com.shared.utils"
})
public class MyApp { ... }

// Or type-safe with marker classes:
@ComponentScan(basePackageClasses = {
    MyApp.class,
    SharedConfig.class  // Spring scans the package containing this class
})

// @Component — you own the class
@Service
public class UserService { ... }

// @Bean — third-party class you can't annotate
@Configuration
public class AppConfig {
    @Bean
    public RestTemplate restTemplate() {
        RestTemplate rt = new RestTemplate();
        rt.setErrorHandler(new CustomErrorHandler());
        return rt;
    }
}

@Service
@Scope("singleton") // default — can omit
public class UserService { ... }

@Component
@Scope("prototype") // new instance per injection
public class ReportBuilder { ... }

@Component
@RequestScope   // new instance per HTTP request
public class RequestContext { ... }

// Field injection (less preferred)
@Service
public class OrderService {
    @Autowired
    private PaymentService paymentService;
}

// Constructor injection (preferred)
@Service
public class OrderService {
    private final PaymentService paymentService;
    public OrderService(PaymentService paymentService) {
        this.paymentService = paymentService;
    }
}
